import dev.unbox.client.EnvironmentManifest;
import java.nio.file.*;
import java.util.zip.*;
public class EnvironmentManifestTest {
 static void jar(Path p,String id,String environment)throws Exception{try(var out=new ZipOutputStream(Files.newOutputStream(p))){out.putNextEntry(new ZipEntry("fabric.mod.json"));out.write(("{\"id\":\""+id+"\",\"version\":\"1.0\",\"environment\":\""+environment+"\"}").getBytes());out.closeEntry();}}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("unbox-manifest-");try{Path mods=Files.createDirectories(root.resolve("mods"));jar(mods.resolve("game.jar"),"example_game","*");jar(mods.resolve("personal.jar"),"personal_hud","client");jar(mods.resolve("server.jar"),"server_tool","server");jar(mods.resolve("managed.jar"),"sodium","client");var snapshot=EnvironmentManifest.scan(root);if(snapshot.files().size()!=1)throw new AssertionError("Personal/server-only mods leaked into shared set");var entry=EnvironmentManifest.validate(snapshot.manifest()).getFirst();if(!entry.hash().equals(EnvironmentManifest.hash(mods.resolve("game.jar"))))throw new AssertionError("Wrong hash");var invalid=snapshot.manifest().deepCopy();invalid.getAsJsonArray("files").add(invalid.getAsJsonArray("files").get(0).deepCopy());try{EnvironmentManifest.validate(invalid);throw new AssertionError("Duplicate accepted");}catch(java.io.IOException expected){}invalid=snapshot.manifest().deepCopy();invalid.addProperty("loader","neoforge");try{EnvironmentManifest.validate(invalid);throw new AssertionError("Unsupported loader accepted");}catch(java.io.IOException expected){}System.out.println("Manifest checks passed: gameplay scope, checksum, duplicate rejection, loader boundary");}finally{try(var all=Files.walk(root)){for(Path p:all.sorted(java.util.Comparator.reverseOrder()).toList())Files.delete(p);}}}
}
